import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import vm from 'node:vm';
const base='8f48dc8ef72ba68197a456b1149c3d652b592d21';
const pkg='snapback2/packages/snapback2/';
const source=readFileSync(pkg+'build.mjs','utf8');
const extract=(start,end)=>source.slice(source.indexOf(start),source.indexOf(end,source.indexOf(start)));
const guideFailures=vm.runInNewContext('('+extract('function guideFailures(', '\n// @ref LLP 1002#8-why-trace-guide')+')',{Buffer});
const guideKeywords=vm.runInNewContext('('+extract('function guideKeywords(', '\nasync function loadQuarryParser(')+')');
const names=['grammar','quarry','auth','live-query','effects','personas','testing','offline','job','schedule'];
const current=names.map(name=>({name,markdown:readFileSync(pkg+'guide/'+name+'.md','utf8')}));
const previous=names.map(name=>({name,markdown:execFileSync('git',['show',base+':'+pkg+'guide/'+name+'.md'],{encoding:'utf8'})}));
const grammar=current[0];
assert(!grammar.markdown.includes('```'), 'grammar has no snippets requiring a compiler build');
const limit=Number(source.match(/name === "grammar" \? (\d+)/)[1]);
const errors=guideFailures([{...grammar,limit}], '', '', null);
assert.equal(errors.length,0,JSON.stringify(errors));
const oldKeywords=JSON.stringify(guideKeywords(previous));
const newKeywords=JSON.stringify(guideKeywords(current));
assert.equal(newKeywords,oldKeywords,'existing package keyword output is unchanged');
for(let i=1;i<names.length;i++) assert.equal(current[i].markdown,previous[i].markdown);
const snippets=text=>JSON.stringify([...text.matchAll(/```[^\n]*\n[\s\S]*?\n```/g)].map(match=>match[0]));
assert.equal(snippets(readFileSync(pkg+'README.md','utf8')),snippets(execFileSync('git',['show',base+':'+pkg+'README.md'],{encoding:'utf8'})));
console.log(JSON.stringify({grammarBytes:Buffer.byteLength(grammar.markdown),grammarLimit:limit,guideFailures:errors,keywordCount:Object.keys(JSON.parse(newKeywords)).length,keywordOutputUnchanged:true,otherGuidePagesUnchanged:true,readmeFencedSnippetsUnchanged:true,scope:'Existing pure package guide validators only; no package build, parser, typecheck or installed-package claim.'},null,2));
